#define CPU_BENCH_NO_MAIN
#include "../reference/cpu/cpu_bench.cpp"
#include "../reference/common/dataset_cache.hpp"
#include "../common/compact_dataset.hpp"
int main(int argc,char**argv){try{
 if(argc==2&&std::string(argv[1])=="--self-test"){selftest();return 0;}
 require(argc==6,"usage: full_cpu COMPACT_FIXTURE NEW_RESULTS REPS WARMUPS descending|ascending");fs::path root=argv[1],dir=argv[2];unsigned reps=count(argv[3],20),warm=count(argv[4],3);std::string order=argv[5];require(reps>0&&(order=="descending"||order=="ascending"),"CPU full counts/order");require(!fs::exists(dir),"CPU result directory exists");fs::create_directories(dir);
 auto setup_start=Clock::now();CachedDataset cache;load_compact_group(cache,root,5);InputCase holder;std::vector<uint64_t> out(cache.chunks.front().expected.size());ComputePool pool(holder,out,2);auto n=cache.chunks.front().input.n,l=cache.chunks.front().input.l,k=cache.chunks.front().input.k;unsigned nchunks=cache.chunks.size();
 std::ofstream setup(dir/"setup.json");setup<<"{\"setup_ms\":"<<elapsed(setup_start,Clock::now())<<",\"threads\":2,\"one_group_cache\":true}\n";setup.close();require(bool(setup),"CPU setup write");
 std::ofstream whole(dir/"iterations.csv"),groups(dir/"groups.csv");whole<<std::fixed<<std::setprecision(6);groups<<std::fixed<<std::setprecision(6);whole<<"repetition,warmup,groups,compute_sum_ms,verified_call_sum_ms,admission_sum_ms,resident_wall_sum_ms,full_six_streamed_wall_ms,verified_words\n";groups<<"repetition,warmup,ordinal,group,admission_ms,compute_ms,verified_call_ms,resident_verified_wall_ms,verified_words\n";std::vector<double> walls,computes,residents;
 for(unsigned rep=0;rep<reps+warm;++rep){auto start=Clock::now();bool iswarm=rep<warm;double compute=0,calls=0,admission=0,resident=0;uint64_t words=0;std::ostringstream grows;grows<<std::fixed<<std::setprecision(6);
  for(unsigned i=0;i<6;++i){unsigned g=order=="ascending"?i:5-i;auto load_start=Clock::now();load_compact_group(cache,root,g);require(cache.chunks.size()==nchunks&&cache.chunks.front().input.n==n&&cache.chunks.front().input.l==l&&cache.chunks.front().input.k==k,"CPU cross-group shape");double load=elapsed(load_start,Clock::now()),gc=0,gt=0;admission+=load;auto resident_start=Clock::now();
   for(auto& chunk:cache.chunks){auto begin=Clock::now();CachedInputLease lease(holder,chunk.input);std::fill(out.begin(),out.end(),UINT64_MAX);auto loaded=Clock::now();pool.run();auto done=Clock::now();compare(out,chunk.expected);lease.restore();gc+=elapsed(loaded,done);gt+=elapsed(begin,Clock::now());}
   double group_resident=elapsed(resident_start,Clock::now());resident+=group_resident;compute+=gc;calls+=gt;words+=cache.golden_bytes/8;grows<<rep<<','<<iswarm<<','<<i<<','<<g<<','<<load<<','<<gc<<','<<gt<<','<<group_resident<<','<<cache.golden_bytes/8<<'\n';
  }
  double wall=elapsed(start,Clock::now());require(words==uint64_t(6)*n*nchunks*l*3,"CPU six-group coverage");groups<<grows.str();whole<<rep<<','<<iswarm<<",6,"<<compute<<','<<calls<<','<<admission<<','<<resident<<','<<wall<<','<<words<<'\n';groups.flush();whole.flush();require(bool(groups)&&bool(whole),"CPU result write");if(!iswarm){walls.push_back(wall);computes.push_back(compute);residents.push_back(resident);}std::cout<<"PASS_FULL_HS4_CPU_SIX_MAC repetition="<<rep<<" warmup="<<iswarm<<" compute_sum_ms="<<compute<<" full_six_streamed_wall_ms="<<wall<<" verified_words="<<words<<'\n'<<std::flush;
 }
 std::ofstream f(dir/"summary.json");f<<std::setprecision(12)<<"{\"status\":\"PASS_FULL_CPU_SIX_MAC_GROUPS\",\"measured\":"<<reps<<",\"warmups\":"<<warm<<",\"threads\":2,\"groups\":6,\"compute_sum_median_ms\":"<<med(computes)<<",\"full_six_streamed_wall_median_ms\":"<<med(walls)<<",\"resident_verified_wall_sum_median_ms\":"<<med(residents)<<",\"scope\":\"Same compact input loader and all-group validation as hardware,one group resident at a time; includes admission,excludes one setup. Historical u128 CPU math; not OpenFHE or optimalCPU claim; not full h_s.4 layer.\"}\n";f.close();require(bool(f),"CPU summary write");return 0;
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
